codeExample.code:
#include <stdio.h>

/* Function prototype */
int add(int a, int b);
void greet(void);

int main(void) {
    int x = 10, y = 20;
    int result;

    greet();                  /* Call void function  */

    result = add(x, y);       /* Call int function   */
    printf("Sum = %d\n", result);

    /* Original values unchanged (call by value) */
    printf("x = %d, y = %d\n", x, y);

    return 0;
}

/* Function definition: no return value */
void greet(void) {
    printf("Welcome to Functions in C!\n");
}

/* Function definition: returns int */
int add(int a, int b) {
    int sum = a + b;
    return sum;
}

