questions.solution:
#include <stdio.h>

/* Function prototype */
int maxOfTwo(int a, int b);

int main(void) {
    int p, q;
    printf("Enter two integers: ");
    scanf("%d %d", &p, &q);
    printf("Larger value = %d\n", maxOfTwo(p, q));
    return 0;
}

/* Function definition */
int maxOfTwo(int a, int b) {
    if (a >= b)
        return a;
    else
        return b;
}

